39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const BASE_PREMIUM_BY_ITEM_TYPE = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	} as const satisfies Record<string, number>;
53	
54	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
55	
56	const BLOCK_SIZE = 3;
57	const BLOCK_BASE_PREMIUM = 60;
58	const CURSE_SURCHARGE_PERCENT = 50;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
61	
62	const basePremiumOf = (item: Item): number =>
63	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
64	
65	const curseSurcharge = (item: Item): number =>
66	  item.cursed ? percentOf(basePremiumOf(item), CURSE_SURCHARGE_PERCENT) : 0;
67	
68	const highEnchantmentSurcharge = (item: Item): number =>
69	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
70	    ? percentOf(basePremiumOf(item), HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
71	    : 0;
72	
73	const itemSurcharges = (item: Item): number =>
74	  curseSurcharge(item) + highEnchantmentSurcharge(item);
75	
76	const sumItemSurcharges = (items: Item[]): number =>
77	  items.reduce((sum, item) => sum + itemSurcharges(item), 0);
78	
79	const groupByType = (items: Item[]): Item[][] => [
80	  ...items
81	    .reduce(
82	      (groups, item) =>
83	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
84	      new Map<string, Item[]>(),
85	    )
86	    .values(),
87	];
88	
89	const basePremiumOfGroup = (group: Item[]): number => {
90	  if (group.length === BLOCK_SIZE) return BLOCK_BASE_PREMIUM;
91	  return group.reduce((sum, item) => sum + basePremiumOf(item), 0);
92	};
93	
94	const policyBasePremium = (items: Item[]): number =>
95	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
96	
97	const quotePremium = (items: Item[]): number => {
98	  const policyBase = policyBasePremium(items);
99	  const premiumBeforeFee =
100	    policyBase +
101	    sumItemSurcharges(items) +
102	    percentOf(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
103	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
104	};
105	
106	const runStep = (step: Step): StepResult => {
107	  if (step.op === "quote") return { premium: quotePremium(step.items) };
108	  throw new Error("claim steps are not implemented yet");
109	};
110	
111	export const runScenario = (scenario: Scenario): ScenarioResult => ({
112	  results: scenario.steps.map(runStep),
113	});
