interface RiskSurcharge {
  applesTo: (item: Item) => boolean;
  percent: number;
}

const RISK_SURCHARGES: RiskSurcharge[] = [
  { applesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
  {
    applesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
  },
];

const itemSurcharge = (item: Item): number =>
  RISK_SURCHARGES.filter((surcharge) => surcharge.applesTo(item)).reduce(
    (sum, surcharge) => sum + percentOf(basePremiumOf(item), surcharge.percent),
    0,
  );

const policySurcharges = (items: Item[]): number =>
  items.reduce((sum, item) => sum + itemSurcharge(item), 0);

